package com.wizzadrds.theworldremembers; import com.wizzadrds.theworldremembers.chronicle.*; import com.wizzadrds.theworldremembers.voice.VoicePacket; import net.fabricmc.api.ClientModInitializer; import net.fabricmc.fabric.api.client.networking.v1.ClientPlayNetworking; import net.minecraft.client.Minecraft; public final class TheWorldRemembersClient implements ClientModInitializer{private static volatile VoicePacket lastVoice; public static VoicePacket lastVoice(){return lastVoice;} public void onInitializeClient(){ClientPlayNetworking.registerGlobalReceiver(VoicePacket.TYPE,(payload,context)->lastVoice=payload);ClientPlayNetworking.registerGlobalReceiver(ChronicleResponsePacket.TYPE,(payload,context)->Minecraft.getInstance().execute(()->Minecraft.getInstance().setScreen(new ChronicleScreen(payload.lines()))));} public static void openChronicles(){ChronicleNetworking.request();}}